"""Provider-independent async transport seam. No credentials, retries or import calls."""

from contextlib import contextmanager
from contextvars import ContextVar

from ..core import models as m
from ..core.errors import ContractViolation

_scope = ContextVar("v2_gateway_decision_ledger", default=None)


class AsyncModelGateway:
    def __init__(self, *, transport, ledger=None):
        self.transport = transport
        self.ledger = ledger

    async def complete(self, request: m.ModelRequest, budget: m.ModelBudget) -> m.ModelResult:
        ledger = _scope.get() or self.ledger
        if ledger is None:
            raise ContractViolation("unsupported_capability: gateway requires a decision-scoped ledger")
        return await ledger.invoke(request, budget, self.transport)

    def model_budget(self, *, task, max_tokens, time_limit_s):
        ledger = _scope.get() or self.ledger
        if ledger is None:
            raise ContractViolation("unsupported_capability: gateway requires a decision-scoped ledger")
        return ledger.model_budget(task=task, max_tokens=max_tokens, time_limit_s=time_limit_s)

    @contextmanager
    def decision_scope(self, ledger):
        token = _scope.set(ledger)
        try:
            yield
        finally:
            _scope.reset(token)

    def admit_raw(self, call_id, raw):
        ledger = _scope.get() or self.ledger
        if ledger is not None:
            ledger.admit_raw(call_id, raw)

    def reject_raw(self, call_id, code, diagnostic=None):
        ledger = _scope.get() or self.ledger
        if ledger is not None:
            ledger.reject_raw(call_id, code, diagnostic)
            )
        else:
            # Read the authoritative zero delta; perform no economic arithmetic.
            choices = [
                o
                for o in request.input.options
                if re.search(r"cost delta from cheapest=0(?:\.0+)? [A-Z]{3}(?:;|$)", o.summary)
            ]
            if not choices:
                raise ContractViolation("unsupported_capability: fixture expects an official minimum offer")
            response = m.SelectorResponse(selected_id=min(o.candidate_id for o in choices), supporting_quote="")
        raw = response.model_dump_json()
        if request.task == "interpret" and request.prompt_version.endswith("-v3"):
            data = json.loads(raw)
            for obs in data["observations"]:
                span = obs["citations"][0]
                obs["citations"] = [
                    next(key for key, value in request.input.citation_catalog if value.message_id == span["message_id"])
                ]
            raw = json.dumps(data)
        return m.ModelSuccess(
            kind="success",
            call_id=request.call_id,
            model_id=request.model_id,
            elapsed_s=Decimal("0"),
            issues=(),
            raw_response_json=raw,
            response_hash=hashlib.sha256(raw.encode()).hexdigest(),
            usage=m.ModelUsage(),
        )

